/*
 * config.h — hand-written LAME configuration for Android (ARM / x86_64).
 *
 * This file is NOT auto-generated by the LAME build system.
 * It is intentionally minimal: only the symbols LAME actually needs at
 * compile time on Android are defined here. Do NOT overwrite this file
 * with the output of `./configure` — the fetch_lame.sh script is written
 * to preserve it.
 *
 * All LAME sources are compiled with -DHAVE_CONFIG_H so that they include
 * this file instead of relying on autoconf output.
 */

#ifndef LAME_CONFIG_H
#define LAME_CONFIG_H

/* ── Standard headers available in the Android NDK sysroot ─────────────── */
#define STDC_HEADERS      1
#define HAVE_STDINT_H     1
#define HAVE_LIMITS_H     1
#define HAVE_STRING_H     1
#define HAVE_STDLIB_H     1
#define HAVE_FCNTL_H      1
#define HAVE_ERRNO_H      1

/* ── Floating-point type alias ──────────────────────────────────────────── */
/*
 * LAME's util.h (upstream) uses `ieee754_float32_t` which is defined by
 * <ieee754.h> on GNU/Linux but is NOT available in the Android NDK sysroot.
 * The fetch_lame.sh patch replaces the extern declaration in util.h with
 * plain `float`, but we also define the type alias here so any remaining
 * references in LAME internals compile cleanly.
 */
typedef float ieee754_float32_t;

/* ── Disable optional LAME subsystems not needed for pure encoding ──────── */
/*
 * HAVE_MPGLIB is intentionally left UNDEFINED. Defining it would pull in
 * mpglib (the MP3 decoder), which we do not vendor and do not need.
 */
/* #undef HAVE_MPGLIB */

/* ── Miscellaneous LAME internal knobs ─────────────────────────────────── */
#define LAME_LIBRARY_BUILD 1

/* Package metadata (used by lame_get_version() etc.) */
#define PACKAGE_VERSION "3.100"
#define PACKAGE_NAME    "lame"

#endif /* LAME_CONFIG_H */
